
e=101


# ~m = -(m+1); e odd => c2 = -(m+1)^e. Franklin-Reiter on f1=x^e-c1, f2=(x+1)^e+c2
from math import comb
def trim(a):
    while a and a[-1]==0: a.pop()
    return a
def pmod(a,b):
    a=a[:]; inv=pow(b[-1],-1,n)
    while len(a)>=len(b):
        k=a[-1]*inv%n; s=len(a)-len(b)
        for i,x in enumerate(b): a[s+i]=(a[s+i]-k*x)%n
        trim(a)
        if not a: break
    return a
def pgcd(a,b):
    while b: a,b=b,pmod(a,b)
    return a
f1=[0]*(e+1); f1[0]=(-c1)%n; f1[e]=1
f2=[comb(e,i)%n for i in range(e+1)]; f2[0]=(f2[0]+c2)%n
g=pgcd(f1,f2)
print(len(g)-1)
m=(-g[0]*pow(g[1],-1,n))%n
print(m.to_bytes(80,'big').lstrip(b'\0'))
